class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        low, high = min(nums), max(nums)
        arr = [0] * (high - low + 1)

        for num in nums:
            arr[num - low] += 1

        for i in range(len(arr) - 1, -1, -1):
            k -= arr[i]
            if k <= 0:
                return i + low

        return -1
